{
 "question": "Group the World Champions among the corpus drivers by decade (2000s, 2010s, 2020s).",
 "answer": "2000s: Michael Schumacher (1996-2006), Kimi Räikkönen (2007), Jenson Button (2009); 2010s: Sebastian Vettel (2009-2014), Nico Rosberg (2016); 2020s: Lewis Hamilton (2020), Max Verstappen (since 2016).",
 "criteria": [
  {
   "id": "Q12-c1",
   "text": "Michael Schumacher belongs in the 2000s championship-winning group.",
   "expected_content": [
    "2000s",
    "Michael Schumacher"
   ],
   "required": true
  },
  {
   "id": "Q12-c2",
   "text": "Fernando Alonso belongs in the 2000s championship-winning group.",
   "expected_content": [
    "2000s",
    "Fernando Alonso"
   ],
   "required": true
  },
  {
   "id": "Q12-c3",
   "text": "Kimi Räikkönen belongs in the 2000s championship-winning group.",
   "expected_content": [
    "2000s",
    "Kimi Räikkönen"
   ],
   "required": true
  },
  {
